import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif

MAX_DRIVERS = 4

def design(feats):
    # Filter features with significant effect size (|mean_y1-mean_y0| > 0.15)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        # Calculate effect size as difference in means between groups
        mean_1 = feats.x[feats.y == 1, i].mean()
        mean_0 = feats.x[feats.y == 0, i].mean()
        effect_size = abs(mean_1 - mean_0)
        if effect_size > 0.15:
            sig_features.append(fid)

    # Remove near-duplicates based on correlation
    keep = []
    used = set()
    for fid in sig_features:
        col_idx = feats.column(fid)
        corr_with_others = []
        for kept_fid in keep:
            kept_idx = feats.column(kept_fid)
            corr = abs(np.corrcoef(feats.x[:, col_idx], feats.x[:, kept_idx])[0,1])
            corr_with_others.append(corr)

        if not corr_with_others or max(corr_with_others) < 0.6:
            keep.append(fid)
            used.add(fid)

    # If no significant features, return empty design
    if not keep:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features by t-statistic
    drivers = []
    for fid in keep[:MAX_DRIVERS]:
        col_idx = feats.column(fid)
        try:
            t_stat = stats.ttest_ind(feats.x[feats.y==1, col_idx], feats.x[feats.y==0, col_idx]).statistic
            if abs(t_stat) > 1.5:
                drivers.append(fid)
        except:
            # If t-test fails, just add the feature
            drivers.append(fid)

    # For products, check pairs with high correlation
    products = []
    for i, fid_a in enumerate(keep):
        for j, fid_b in enumerate(keep[i+1:], i+1):
            idx_a = feats.column(fid_a)
            idx_b = feats.column(fid_b)
            try:
                corr = np.corrcoef(feats.x[:, idx_a], feats.x[:, idx_b])[0,1]
                if abs(corr) >= 0.6:
                    products.append((fid_a, fid_b))
            except:
                continue

    # For loadings, use mutual information to rank features
    try:
        mi_scores = mutual_info_classif(feats.x[:, [feats.column(fid) for fid in keep]], feats.y)
        loadings = dict(zip(keep, mi_scores))
    except:
        # Fallback to simple variance-based weights
        loadings = {}
        for fid in keep:
            col_idx = feats.column(fid)
            loadings[fid] = np.var(feats.x[:, col_idx])

    return Design(
        drivers=tuple(drivers),
        columns=tuple(keep),
        products=tuple(products),
        loadings=loadings
    )

